/**
 * Build-time constants injected by Vite's `define`.
 *
 * `__DEV_SERVER_STARTED_AT__` is substituted textually before TypeScript ever
 * sees the bundle, so it needs a declaration here or `main.tsx` will not
 * typecheck. See the note in `vite.config.ts` for what it is for.
 */
declare const __DEV_SERVER_STARTED_AT__: string;
